<script>
  import Card from "../components/Card.svelte";
  import StatisticsBlock from "../components/StatisticsBlock.svelte";
  import { getUser, getUserProfile, updateUserStats } from "../firebase";
  import { onMount } from "svelte";
  import { profilePhotoLocation } from "../utils";
  import { Modal } from 'svelte-simple-modal';
  import ProfilePhotoContent from "../components/ProfilePhotoContent.svelte";



  // svelte-ignore unused-export-let
  export let currentRoute;
  // svelte-ignore unused-export-let
  export let params;

  let gamesPlayed, easyGamesPlayed, mediumGamesPlayed, hardGamesPlayed, impossibleGamesPlayed;
  let userName = getUser().email.substr(0, getUser().email.indexOf("@"))
  let avgWPM, avgEasyWPM, avgMediumWPM, avgHardWPM, avgImpossibleWPM;
  let avgLPM, avgEasyLPM, avgMediumLPM, avgHardLPM, avgImpossibleLPM;
  let passRate, easyPassRate, mediumPassRate, hardPassRate, impossiblePassRate;
  let src = profilePhotoLocation + 'photo0.png';
  let currentAvatar = 0;
  let newAvatar = 0;


  onMount(() => {
    getUserProfile(getUser().uid).then(res => {
      easyGamesPlayed = res.easyGamesFailed + res.easyGamesWon;
      mediumGamesPlayed = res.mediumGamesFailed + res.mediumGamesWon;
      hardGamesPlayed = res.hardGamesFailed + res.hardGamesWon;
      gamesPlayed = easyGamesPlayed + mediumGamesPlayed + hardGamesPlayed;
      let gamesWon = res.easyGamesWon + res.mediumGamesWon + res.hardGamesWon;
      avgEasyWPM = res.easyWPM;
      avgEasyLPM = res.easyLPM;
      avgMediumWPM = res.mediumWPM;
      avgMediumLPM = res.mediumLPM;
      avgHardWPM = res.hardWPM;
      avgHardLPM = res.hardLPM;
      avgWPM = gamesPlayed != 0 ? (avgEasyWPM*res.easyGamesWon + avgMediumWPM*res.mediumGamesWon + avgHardWPM*res.hardGamesWon) / gamesWon : 0;
      avgLPM = gamesPlayed != 0 ? (avgEasyLPM *res.easyGamesWon + avgMediumLPM*res.mediumGamesWon + avgHardLPM*res.hardGamesWon) / gamesWon : 0;
      easyPassRate = easyGamesPlayed != 0 ? Math.round(res.easyGamesWon / easyGamesPlayed * 100) / 100 : 0;
      mediumPassRate = mediumGamesPlayed != 0 ?  Math.round(res.mediumGamesWon / mediumGamesPlayed * 100) / 100 : 0;
      hardPassRate = hardGamesPlayed != 0 ? Math.round(res.hardGamesWon / hardGamesPlayed * 100) / 100 : 0;
      passRate = gamesPlayed != 0 ? Math.round((gamesWon ) / gamesPlayed * 100) / 100: 0;
      if (res.profilePhoto == null) {
        updateUserStats(getUser().uid, {profilePhoto: 0})
      } else {
        currentAvatar = res.profilePhoto;
        newAvatar = currentAvatar;
        src = profilePhotoLocation + 'photo' + res.profilePhoto + '.png';
      }
    });
  });

  // profile selection functions
  const idPrefix = "profile-photo-";
  function switchAvatar(e) {
    const currentSelectedAvatarID=idPrefix+newAvatar;
    if (e.target.id != currentSelectedAvatarID) {
      // currentAvatar = e.target.id.substr(idPrefix.length)
      let clickedAvatar = document.getElementById(e.target.id);
      clickedAvatar.classList.remove("nonselected-avatar");
      clickedAvatar.classList.add("selected-avatar");
      let currentSelectedAvatar = document.getElementById(currentSelectedAvatarID);
      currentSelectedAvatar.classList.remove("selected-avatar")
      currentSelectedAvatar.classList.add("nonselected-avatar")
      newAvatar = e.target.id.substr(idPrefix.length);
    }

  }

  async function applyChanges() {
    currentAvatar = newAvatar;
    src = profilePhotoLocation + 'photo' + newAvatar + '.png';
    updateUserStats(getUser().uid, {profilePhoto: newAvatar});
  }

  function cancelChanges() {
    const currentSelectedAvatarID=idPrefix+newAvatar;
    let currentSelectedAvatar = document.getElementById(currentSelectedAvatarID);
    currentSelectedAvatar.classList.remove("selected-avatar")
    currentSelectedAvatar.classList.add("nonselected-avatar")
    newAvatar = currentAvatar;
  }

</script>

<style>
  img {
    border-radius: 50%;
    height: 50px;
    width: auto;
  }

  .card-collection {
    justify-content: center;
    display:inline-flex;
    flex-wrap:wrap;
    padding: 5px;
    align-items: center;
    justify-content: center;
    gap: 20px;
  }
</style>

<main>
  <h1>profile</h1>
  {#if gamesPlayed != null}
    <Card title={userName}>
      <StatisticsBlock>
        <img {src} alt="Avatar" />
      </StatisticsBlock>
      <br>
      <Modal>
        <ProfilePhotoContent currentAvatar={currentAvatar} switchAvatar={switchAvatar} applyChanges={applyChanges} cancelChanges={cancelChanges}/>
      </Modal>
    </Card>
    <br>
    <div class="card-collection">
      <Card title="total games">
        <StatisticsBlock overall={gamesPlayed} easy={easyGamesPlayed} medium={mediumGamesPlayed} hard={hardGamesPlayed} impossible={impossibleGamesPlayed} units=""/>
      </Card>
      <Card title="pass rate">
        <StatisticsBlock overall={passRate*100} easy={easyPassRate*100} medium={mediumPassRate*100} hard={hardPassRate*100} impossible={impossiblePassRate} units="%"/>
      </Card>
      <Card title="avg words per minute">
        <StatisticsBlock overall={avgWPM} easy={avgEasyWPM} medium={avgMediumWPM} hard={avgHardWPM} impossible={avgImpossibleWPM} units=""/>
      </Card>
      <Card title="avg letters per minute">
        <StatisticsBlock overall={avgLPM} easy={avgEasyLPM} medium={avgMediumLPM} hard={avgHardLPM} impossible={avgImpossibleLPM} units=""/>
      </Card>
    </div>
  {/if}

  
    
</main>